//! The partial-knowledge layout corpus of the pathfinding plans, regenerated by layout number.
//!
//! # Responsibility
//! Builds layout `n` of the corpus that plan `2026-11-19-partial-knowledge-funnel` §4.3 and §4.4
//! measured and plan `2026-11-20-tastar-budget` (B-149) names its cases by ("layout 25 q 11"): the
//! default arena with 2 to 13 structures drawn by a `SplitMix64` stream, each structure known or
//! not as a whole, or (per cell) each of its cells known or not, and 16 requests between cell
//! centres. Structures are full squares or the 5.0.14 contours of the same `Place` sizes.
//!
//! # How it fits
//! `pathfinding_properties.rs` includes this file with `#[path = "support/layouts.rs"] mod
//! layouts;`, beside `support/arena.rs` as `mod arena`, for the oracle test over the corpus and for the B-149 cases it names. The draw
//! order is the corpus's own, so layout `n` request `q` here is the request the plans measured.
//!
//! # Invariants
//! - A layout is a pure function of its number and kind: integer draws only, every target alike.
//! - Every request of a layout is drawn, fitting or not, so request `q` is the `q`-th drawn.

use sim_map::{GameMap, StructureFootprint};
use sim_types::{EntityId, FootprintShape, SimScalar, SimVec2};

use super::arena;

/// One draw of the corpus's generator (`SplitMix64`), below `bound`.
pub fn layout_draw(state: &mut u64, bound: u64) -> u64 {
    *state = state.wrapping_add(0x9E37_79B9_7F4A_7C15);
    let mut z = *state;
    z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
    z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
    z ^= z >> 31;
    z % bound
}

/// The 5.0.14 footprints the corpus draws: `Place` width and height in cells, then the contour's
/// half width, half height and chamfer in quarter cells.
const SHAPES: [(u8, u8, u16, u16, u16); 7] = [
    (5, 5, 10, 10, 6),
    (3, 3, 6, 6, 2),
    (3, 3, 6, 6, 3),
    (2, 2, 4, 4, 2),
    (2, 2, 2, 2, 1),
    (1, 1, 2, 2, 0),
    (3, 2, 6, 4, 2),
];

/// The shipped terrain radii, in sixteenths of a cell.
const RADII: [i64; 9] = [5, 6, 8, 9, 10, 12, 14, 15, 16];

/// Requests drawn per layout.
pub const REQUESTS_PER_LAYOUT: usize = 16;

/// Which of the corpus's four kinds a layout is.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct LayoutKind {
    /// 5.0.14 contours instead of full squares.
    pub contours: bool,
    /// Knowledge drawn per cell instead of per structure.
    pub per_cell: bool,
}

impl LayoutKind {
    /// Full squares, each known or not as a whole.
    pub const WHOLE_SQUARES: Self = Self {
        contours: false,
        per_cell: false,
    };
    /// Contours, each known or not as a whole.
    pub const WHOLE_CONTOURS: Self = Self {
        contours: true,
        per_cell: false,
    };
    /// Full squares, each cell known or not.
    pub const PER_CELL_SQUARES: Self = Self {
        contours: false,
        per_cell: true,
    };
    /// Contours, each cell known or not.
    pub const PER_CELL_CONTOURS: Self = Self {
        contours: true,
        per_cell: true,
    };
}

/// One request of a layout: endpoints in world units and the disc's radius.
#[derive(Debug, Clone, Copy)]
pub struct LayoutRequest {
    /// Start, a cell centre.
    pub start: SimVec2,
    /// Goal, a cell centre.
    pub goal: SimVec2,
    /// The disc's radius, one of the shipped terrain radii.
    pub radius: SimScalar,
}

/// A generated layout.
pub struct Layout {
    /// The arena with every structure.
    pub map: GameMap,
    /// The arena with only the structures known as a whole (the oracle's free space); for a
    /// per-cell kind it holds none.
    pub known_map: GameMap,
    /// Per cell, whether the requests know the structure on it (row-major).
    pub known: Vec<bool>,
    /// The layout's requests, in draw order.
    pub requests: Vec<LayoutRequest>,
}

fn footprint(index: usize, contours: bool) -> StructureFootprint {
    let (width, height, half_width_q, half_height_q, chamfer_q) = SHAPES[index];
    if !contours {
        return StructureFootprint::square(width, height);
    }
    StructureFootprint {
        width,
        height,
        shape: FootprintShape::Box {
            half_width_q,
            half_height_q,
            chamfer_q,
        },
    }
}

/// Layout `number` of the corpus of kind `kind`.
///
/// # Panics
/// If a structure the arena accepted is refused by the known-only arena, which holds a subset.
#[must_use]
pub fn layout(number: u64, kind: LayoutKind) -> Layout {
    let mut state = number.wrapping_mul(0x9E37_79B9_7F4A_7C15) ^ 0x5eed;
    let mut map = arena::default_arena();
    let mut known_map = arena::default_arena();
    let count = 2 + u32::try_from(number % 12).unwrap_or(0);
    let mut placed = 0;
    let mut whole_known = Vec::new();
    for attempt in 0..count * 6 {
        if placed == count {
            break;
        }
        let shape = usize::try_from(layout_draw(&mut state, 7)).unwrap_or(0);
        let cell = (
            u32::try_from(layout_draw(&mut state, u64::from(map.width() - 5))).unwrap_or(0),
            u32::try_from(layout_draw(&mut state, u64::from(map.height() - 5))).unwrap_or(0),
        );
        let is_known = layout_draw(&mut state, 2) == 0;
        let id = EntityId(40_000 + attempt);
        if map
            .place_structure(id, cell, footprint(shape, kind.contours))
            .is_ok()
        {
            placed += 1;
            whole_known.push((id, is_known));
            if is_known && !kind.per_cell {
                assert!(known_map
                    .place_structure(id, cell, footprint(shape, kind.contours))
                    .is_ok());
            }
        }
    }
    let width = map.width();
    let mut known = vec![false; (map.width() * map.height()) as usize];
    for (id, structure) in map.structures() {
        let whole = whole_known
            .iter()
            .find(|(placed_id, _)| placed_id == id)
            .is_some_and(|&(_, is_known)| is_known);
        let (left, top) = structure.top_left;
        for y in top..top + u32::from(structure.height) {
            for x in left..left + u32::from(structure.width) {
                known[(y * width + x) as usize] = if kind.per_cell {
                    layout_draw(&mut state, 2) == 0
                } else {
                    whole
                };
            }
        }
    }
    let mut requests = Vec::with_capacity(REQUESTS_PER_LAYOUT);
    for _ in 0..REQUESTS_PER_LAYOUT {
        let mut centre = || {
            let x = u32::try_from(layout_draw(&mut state, u64::from(map.width()))).unwrap_or(0);
            let y = u32::try_from(layout_draw(&mut state, u64::from(map.height()))).unwrap_or(0);
            map.cell_to_world_center(x, y)
        };
        let (start, goal) = (centre(), centre());
        let sixteenths = RADII[usize::try_from(layout_draw(&mut state, 9)).unwrap_or(0)];
        if let (Ok(start), Ok(goal)) = (start, goal) {
            requests.push(LayoutRequest {
                start,
                goal,
                radius: SimScalar::from_raw(sixteenths << 28),
            });
        }
    }
    Layout {
        map,
        known_map,
        known,
        requests,
    }
}
